stic\n+thread races without changing exhaustive search semantics.\n+\n+## Entrypoints\n+\n+`compile.sh` is idempotent. On Windows it creates only `executable.cmd`; on\n+Unix-like systems it creates `executable` as directly runnable Python source.\n+The implementation itself remains in `zip_password_finder_port.py`.\n+\n+## Verification\n+\n+`test_port.py` covers parser helpers, candidate ordering, both encryption\n+families, and end-to-end fixtures. `differential_verify.py` compares the port\n+with the official binary over generated validation and fixture cases. Elapsed\n+time is checked by syntax rather than equality because independent executions\n+necessarily report different measured durations.\n*** Add File: zip_password_finder_port.py\n+#!/usr/bin/env python3\n+\"\"\"Standalone functional port of zip-password-finder 0.11.1.\"\"\"\n+\n+from __future__ import annotations\n+\n+import binascii\n+import bz2\n+import hashlib\n+import hmac\n+import itertools\n+import lzma\n+import os\n+import struct\n+import sys\n+import time\n+import zlib\n+from dataclasses import dataclass\n+from pathlib import Path\n+from typing import Iterable, Iterator\n+\n+APP = \"zip-password-finder.exe\" if os.name == \"nt\" else \"zip-password-finder\"\n+VERSION = \"0.11.1\"\n+LOWER = \"abcdefghijklmnopqrstuvwxyz\"\n+UPPER = \"ABCDEFGHIJKLMNOPQRSTUVWXYZ\"\n+DIGITS = \"0123456789\"\n+SYMBOLS = \" !\\\"#$%&'()*+,-./:;<=>?@[\\\\]^_`{|}~\"\n+BUILTINS = {\n+    \"l\": LOWER,\n+    \"u\": UPPER,\n+    \"d\": DIGITS,\n+    \"s\": SYMBOLS,\n+    \"a\": LOWER + UPPER + DIGITS + SYMBOLS,\n+    \"h\": DIGITS + \"abcdef\",\n+    \"H\": DIGITS + \"ABCDEF\",\n+}\n+\n+HELP = f\"\"\"Find the password of protected ZIP files\n+\n+Usage: {APP} [OPTIONS] --inputFile <inputFile>\n+\n+Options:\n+  -i, --inputFile <inputFile>\n+          path to zip input file\n+\n+  -w, --workers <workers>\n+          number of workers\n+\n+  -p, --passwordDictionary <passwordDictionary>\n+          path to a password dictionary file\n+\n+  -c, --charset <charset>\n+          charset to use to generate password\n+          \n+          [default: lud]\n+\n+      --charsetFile <charsetFile>\n+          path to a charset file\n+\n+      --minPasswordLen <minPasswordLen>\n+          minimum password length\n+          \n+          [default: 1]\n+\n+      --maxPasswordLen <maxPasswordLen>\n+          maximum password length\n+          \n+          [default: 10]\n+\n+      --fileNumber <fileNumber>\n+          file number in the zip archive\n+          \n+          [default: 0]\n+\n+  -s, --startingPassword <startingPassword>\n+          password to start from\n+\n+  -m, --mask <mask>\n+          mask pattern for mask attack (e.g. '?l?l?l?d?d' for 3 lowercase + 2 digits).\n+          \n+          Available tokens:\n+            ?l  lowercase letters [a-z]\n+            ?u  uppercase letters [A-Z]\n+            ?d  digits [0-9]\n+            ?s  symbols\n+            ?a  all printable (?l?u?d?s)\n+            ?h  lowercase hex [0-9a-f]\n+            ?H  uppercase hex [0-9A-F]\n+            ?1  custom charset 1 (--customCharset1)\n+            ?2  custom charset 2 (--customCharset2)\n+            ?3  custom charset 3 (--customCharset3)\n+            ?4  custom charset 4 (--customCharset4)\n+            ??  literal '?'\n+          \n+          Any other character is treated as a literal.\n+\n+  -1, --customCharset1 <customCharset1>\n+          custom charset 1 for mask attack, referenced as ?1 (e.g. 'aeiou' or '?l?d')\n+\n+  -2, --customCharset2 <customCharset2>\n+          custom charset 2 for mask attack, referenced as ?2\n+\n+  -3, --customCharset3 <customCharset3>\n+          custom charset 3 for mask attack, referenced as ?3\n+\n+  -4, --customCharset4 <customCharset4>\n+          custom charset 4 for mask attack, referenced as ?4\n+\n+  -h, --help\n+          Print help (see a summary with '-h')\n+\n+  -V, --version\n+          Print version\n+\"\"\"\n+\n+\n+class CliExit(Exception):\n+    de